function test_ok($condition,$name){if(!$condition)throw new RuntimeException('FAIL: '.$name);echo 'PASS: '.$name.PHP_EOL;}
function test_reject($fn,$name){try{$fn();}catch(PDOException $e){throw $e;}catch(InvalidArgumentException $e){echo 'PASS: '.$name.PHP_EOL;return;}catch(RuntimeException $e){echo 'PASS: '.$name.PHP_EOL;return;}throw new RuntimeException('FAIL: '.$name);}
