        elseif($argv[2]==='commission')(new ActivityService($pdo))->processCommission((int)$argv[3],(int)$argv[4],$argv[5]);
        else throw new RuntimeException('未知测试操作');
        echo 'OK';exit(0);
    }catch(Exception $e){echo 'REJECT: '.$e->getMessage();exit(2);}
}
function test_parallel($jobs){
    $running=array();foreach($jobs as $job){$pipes=array();$process=proc_open(array_merge(array(PHP_BINARY,__FILE__,'--worker'),$job),array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w')),$pipes);if(!is_resource($process))throw new RuntimeException('无法启动并发测试');fclose($pipes[0]);$running[]=array($process,$pipes);}
    $success=0;foreach($running as $child){$out=stream_get_contents($child[1][1]);$err=stream_get_contents($child[1][2]);fclose($child[1][1]);fclose($child[1][2]);$exit=proc_close($child[0]);if($exit===0&&$out==='OK')$success++;elseif($exit!==2||strpos($out,'REJECT: ')!==0)throw new RuntimeException('并发进程异常：'.$out.$err);}
    return $success;
}
